#include <bits/stdc++.h>
#define endl '\n'

using namespace std;

using ll = long long;

const ll N = 2e5 + 5, P = 998244353;

int n;
bool a[N];
ll f[2][2][2][2][2][2][2];
string s;

void init() {}

ll dfs(int k, bool l1, bool l2, bool l3, bool f1, bool f2, bool f3)
{
	cerr << k << endl;
	if (k > n)
		return f1 & f2 & f3;
	if (f[k][l1][l2][l3][f1][f2][f3] != -1)
		return f[k][l1][l2][l3][f1][f2][f3];
	f[k][l1][l2][l3][f1][f2][f3] = 0;
	for (int x = 0; x <= (l1 ? a[k] : 1); ++x)
	{
		for (int y = 0; y <= (l2 ? a[k] : 1); ++y)
		{
			for (int z = 0; z <= (l3 ? a[k] : 1); ++z)
				(f[k][l1][l2][l3][f1][f2][f3] += dfs(k + 1, l1 & (x == a[k]), l2 & (y == a[k]), l3 & (z == a[k]), f1 | (!x && y && z) | (x && !y && !z),
													 f2 | (!y && x && z) | (y && !x && !z), f3 | (!z && x && y) | (z && !x && !y))) %= P;
		}
	}
	return f[k][l1][l2][l3][f1][f2][f3];
}

void solve()
{
	cin >> s;
	n = s.size();
	s = ' ' + s;
	for (int i = 1; i <= n; ++i)
		a[i] = s[i] - 48;
	memset(f, -1, sizeof f);
	cout << dfs(1, 1, 1, 1, 1, 1, 1) << endl;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout.tie(nullptr);
	int _ = 1;
	// cin >> _;
	init();
	while (_--)
		solve();
	return 0;
}

